{
  "application": "ppt-generation",
  "case_id": "case-cloudflare-year-review",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 7,
    "audience": "Technology executives and network infrastructure leaders",
    "tone": "Professional, data-driven, authoritative"
  },
  "brief": {
    "title": "Cloudflare Radar 2024 Year in Review",
    "one_liner": "A data-driven analysis of global Internet traffic, adoption trends, connectivity disruptions, and security threats observed through Cloudflare's network in 2024.",
    "goal": "Present the most significant Internet trends from 2024, including traffic growth, technology adoption shifts, connectivity challenges, and the evolving security landscape, to inform strategic planning for network and security leaders."
  },
  "slides": [
    {
      "id": "slide-01",
      "title": "Cloudflare Radar 2024 Year in Review",
      "objective": "Title slide introducing the report scope: Internet patterns and trends observed through Cloudflare's global network during 2024."
    },
    {
      "id": "slide-02",
      "title": "17% Global Traffic Growth and Starlink's 3.3x Surge",
      "objective": "Present overall Internet traffic growth of 17% and highlight SpaceX Starlink's 3.3x traffic increase as satellite connectivity expands to underserved regions."
    },
    {
      "id": "slide-03",
      "title": "Google Leads Top 10 Services as Generative AI Rises",
      "objective": "Show the top 10 most popular Internet services ranking with Google at #1, and discuss the continued meteoric rise of generative AI throughout 2024."
    },
    {
      "id": "slide-04",
      "title": "Post-Quantum Encryption Jumps from 2% to 13% of TLS 1.3",
      "objective": "Illustrate the dramatic adoption curve of post-quantum encryption following Chrome 124's default enablement, and cover HTTP/3 adoption at 21% and Go as the top API client language."
    },
    {
      "id": "slide-05",
      "title": "225 Major Disruptions: Government Shutdowns Lead Outage Causes",
      "objective": "Analyze the 225 observed Internet disruptions by cause, highlighting government-directed shutdowns as the leading cause, followed by cable cuts (41) and power outages (16)."
    },
    {
      "id": "slide-06",
      "title": "6.5% of Traffic Mitigated: Persistent Threats and Bot Concentration",
      "objective": "Present security findings including 6.5% traffic mitigation rate, Gambling/Games as most attacked sector, Log4j's continued exploitation, and email security metrics (4.3% malicious emails)."
    },
    {
      "id": "slide-07",
      "title": "Five Takeaways Shaping the 2025 Internet Outlook",
      "objective": "Summarize the five key findings: traffic growth trajectory, post-quantum encryption momentum, connectivity fragility from government actions, persistent security threats, and the evolving developer ecosystem."
    }
  ]
}

