const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

// Dark Cloudflare Radar theme
const theme = {
  primary: "ffffff",    // White titles
  secondary: "cbd5e1",  // Light grey text
  accent: "f48120",     // Orange accent
  light: "1e293b",      // Dark grey-blue boxes
  bg: "0f172a"          // Navy background
};

for (let i = 1; i <= 7; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: '/app/output/final_deck.pptx' }).then(() => {
    console.log("Done");
});

const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'cover', index: 1, title: 'Cloudflare Radar 2024 Year in Review' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.2, fill: { color: theme.accent }
  });

  slide.addText(slideConfig.title, {
    x: 1, y: 2.2, w: 8, h: 1.2,
    fontSize: 48, fontFace: "Arial",
    color: theme.primary, bold: true, align: "center"
  });

  slide.addText("A data-driven analysis of global Internet traffic, adoption trends, connectivity disruptions, and security threats.", {
    x: 1.5, y: 3.5, w: 7, h: 1,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary, align: "center"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

const pptxgen = require("pptxgenjs");
const slideConfig = { type: 'content', index: 2, title: "17% Global Traffic Growth and Starlink's 3.3x Surge" };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true
  });
  slide.addShape(pres.shapes.LINE, { x: 0.5, y: 1.2, w: 9, h: 0, line: { color: theme.accent, width: 2 } });

  slide.addText([
    { text: "Global Internet Traffic\n", options: { bold: true, color: theme.accent, fontSize: 22 } },
    { text: "• Grew by 17% in 2024, continuing a strong upward trend.\n", options: { fontSize: 18 } },
    { text: "• Driven by increasing reliance on communication, commerce, and entertainment.\n\n", options: { fontSize: 18 } },
    { text: "SpaceX Starlink\n", options: { bold: true, color: theme.accent, fontSize: 22 } },
    { text: "• Traffic saw dramatic 3.3x growth globally.\n", options: { fontSize: 18 } },
    { text: "• Continues expanding satellite Internet to previously underserved locations.", options: { fontSize: 18 } }
  ], {
    x: 0.5, y: 1.5, w: 4.5, h: 3.5,
    color: theme.secondary, fontFace: "Arial", bullet: false, valign: "top"
  });

  slide.addImage({ path: "imgs/starlink-traffic-growth-2024.jpg", x: 5.2, y: 1.6, w: 4.3, h: 3.2 });

  // Badge
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: 9.1, y: 5.15, w: 0.6, h: 0.35, fill: { color: theme.accent }, rectRadius: 0.15 });
  slide.addText("02", { x: 9.1, y: 5.15, w: 0.6, h: 0.35, fontSize: 11, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}
module.exports = { createSlide, slideConfig };

